@pytest.mark.parametrize("staged", [False, True]) def test_failed_report_cannot_reread_operator_repaired_bytes(tmp_path, monkeypatch, staged): store = FileSystemCAS(tmp_path / "cas", ownership_enforced=False) ref = store.put_bytes(b"original", PutOptions(kind="snapshot", media_type="text/plain")) blob, manifest = store._paths(ref.artifact_id) root = store.root if staged: root = tmp_path / "stage" staged_blob = root / blob.relative_to(store.root) staged_manifest = root / manifest.relative_to(store.root) staged_blob.parent.mkdir(parents=True) staged_blob.write_bytes(blob.read_bytes()) staged_manifest.write_bytes(manifest.read_bytes()) blob = staged_blob damaged = b"old damaged snapshot" blob.write_bytes(damaged) actual_read = store._read_cas_file_no_follow actual_hash = store_module.content_hash reads, hashes = [], []
